-- Boleh dijalankan ulang: isinya akan diperbarui, tidak dobel.
insert into lessons (id,title,emoji,color,sort_order,lang,pages,questions) values
('healthy-food-1','Healthy Food','🥦','grass',6,'en',$j$[{"video": "fE8lezHs19s", "emoji": "🎬", "text": "Let's watch! 🎬"}, {"video": "e1wLP6hByEE", "emoji": "🎬", "text": "Let's watch again! 🎬"}, {"emoji": "🥦🍎🐟", "text": "Healthy food: foods that help to keep the body strong.\n\nRice, bean, soup, fish, chicken, egg, apple, banana, orange, salad, milk, tomato, corn, carrot, lettuce."}, {"emoji": "🍟🍬🥤", "text": "Unhealthy food: foods that don't help to keep the body strong, even if they taste good.\n\nFizzy drink, ice cream, candy, chocolate, French fries, burger, pizza, chips."}, {"emoji": "👦🥑", "text": "Assalamu'alaykum... My name is Ahmed. I like eating healthy food because it is good for my body.\n\nMy mom likes making healthy food for me. Sometimes I help her.\n\nI eat lots of vegetables and fruits every day, so I will become smart, healthy, and strong."}, {"emoji": "📖", "text": "Islamic Value: Al-Baqarah 168\n\nAllah tells us to eat food that is halal and good (halalan thayyiban).\n\n\"Wahai manusia, makanlah sebagian (makanan) di bumi yang halal lagi baik, dan janganlah mengikuti langkah-langkah setan.\""}]$j$::jsonb,$j$[{"q": "Which one is healthy food?", "options": ["🥕 Carrot", "🍬 Candy", "🥤 Fizzy drink"], "answer": 0}, {"q": "Which one is unhealthy food?", "options": ["🍎 Apple", "🍔 Burger", "🐟 Fish"], "answer": 1}, {"q": "Healthy food helps to keep our body …", "options": ["💪 strong", "🤒 sick", "😴 sleepy"], "answer": 0}, {"q": "Is chocolate 🍫 healthy food?", "options": ["Yes", "No"], "answer": 1}, {"q": "Strawberries 🍓 are …", "options": ["healthy food", "unhealthy food"], "answer": 0}, {"q": "Cookies 🍪 are …", "options": ["healthy food", "unhealthy food"], "answer": 1}, {"q": "Which one is NOT healthy?", "options": ["🥗 Salad", "🍟 French fries", "🥛 Milk"], "answer": 1}, {"q": "Why does Ahmed like eating healthy food?", "options": ["It is good for his body", "It is sweet", "It is cheap"], "answer": 0}, {"q": "Who makes healthy food for Ahmed?", "options": ["👩 His mom", "👨‍🏫 His teacher", "👦 His friend"], "answer": 0}, {"q": "Ahmed eats lots of vegetables and fruits. He will become …", "options": ["smart, healthy, and strong", "tired and sick"], "answer": 0}, {"q": "Al-Baqarah 168 tells us to eat food that is …", "options": ["halal and good", "sweet and cold", "big and fast"], "answer": 0}]$j$::jsonb),
('healthy-food-2','Our Favourite Food','🍉','coral',7,'en',$j$[{"video": "ddDN30evKPc", "emoji": "🎬", "text": "Let's watch! 🎬"}, {"video": "2U4kYVXEgXw", "emoji": "🎬", "text": "Let's watch again! 🎬"}, {"emoji": "👍👎", "text": "Like and dislike\n\nI like broccoli. I don't like candy.\nShe likes watermelon. She doesn't like pizza.\nHe likes fish. He doesn't like burger."}, {"emoji": "💡", "text": "Remember!\n\nI like → She likes / He likes\nI don't like → She doesn't like / He doesn't like"}, {"emoji": "👦🍞", "text": "Assalamu'alaykum... My name's Musa. I have a big sister, Aisyah, and one little brother, Harun.\n\nOn weekdays, I always have toast with jam and chocolate milk for breakfast."}, {"emoji": "🧕🍚", "text": "My big sister Aisyah doesn't like chocolate milk. She likes rice and egg for breakfast."}, {"emoji": "👶🐟", "text": "Harun really likes fish. He doesn't like egg. He likes fish and rice, or fish and potato.\n\nWhat about fruit? We like all fruits, especially watermelon! 🍉"}, {"emoji": "⭐", "text": "My favourite food is …\n\nExample: My favourite food is fish soup. What is yours?"}]$j$::jsonb,$j$[{"q": "What food does Aisyah like for breakfast?", "options": ["🍚🥚 Rice and egg", "🍫🥛 Chocolate milk", "🍕 Pizza"], "answer": 0}, {"q": "Does Aisyah like chocolate milk?", "options": ["Yes, she does.", "No, she doesn't."], "answer": 1}, {"q": "What food does Harun like?", "options": ["🐟 Fish", "🥚 Egg", "🍬 Candy"], "answer": 0}, {"q": "Does Harun like egg?", "options": ["Yes, he does.", "No, he doesn't."], "answer": 1}, {"q": "Does Musa like watermelon? 🍉", "options": ["Yes, he does.", "No, he doesn't."], "answer": 0}, {"q": "What does Musa have for breakfast?", "options": ["🍞 Toast with jam and chocolate milk", "🍚 Rice and egg", "🐟 Fish and potato"], "answer": 0}, {"q": "She ___ pizza. 🍕❌", "options": ["doesn't like", "don't like"], "answer": 0}, {"q": "He ___ fish. 🐟✅", "options": ["likes", "like"], "answer": 0}, {"q": "I ___ like candy. 🍬❌", "options": ["don't", "doesn't"], "answer": 0}, {"q": "\"Aku suka brokoli\" in English is …", "options": ["I like broccoli.", "She likes broccoli.", "I don't like broccoli."], "answer": 0}]$j$::jsonb)
on conflict (id) do update set title=excluded.title, emoji=excluded.emoji, color=excluded.color,
